<?php
$records = query('SELECT * FROM comments WHERE deleted=0 ORDER BY created DESC,id DESC')->fetchAll();
$records = array_filter($records, fn ($c) => (!param($_GET, 'q') || mb_stripos($c['body'] . ' ' . $c['username'], param($_GET, 'q')) !== false) && (!param($_GET, 'status') || (param($_GET, 'status') === 'pending' ? $c['moderation_reason'] !== null : $c['moderation_reason'] === null)));
[$records,$page,$pages,$total] = admin_page($records);
?>
<form class="admin-filter-form" action="/admin/comments"><input type="search" name="q" aria-label="Search comments" value="<?= e(param($_GET, 'q')) ?>" placeholder="Find text or author"><select name="status" aria-label="Filter comments"><?php foreach (['' => 'All comments', 'pending' => 'Held for review', 'published' => 'Published'] as $key => $label): ?><option value="<?= $key ?>" <?= param($_GET, 'status') === $key ? 'selected' : '' ?>><?= $label ?></option><?php endforeach; ?></select><button>Search comments</button></form><p><?= number_format($total) ?> <?= $total === 1 ? 'comment' : 'comments' ?></p>
<?php foreach ($records as $c): ?><article class="prototype-panel"><div class="comment-heading"><strong><?= e($c['username']) ?></strong><span><?php render_time((int)$c['created']); ?></span></div><p><a href="/art/<?= (int)$c['artwork_id'] ?>#comments">Artwork #<?= (int)$c['artwork_id'] ?> →</a><?= $c['archived'] ? ' · Archived' : '' ?></p><?php if ($c['moderation_reason'] !== null): ?><p class="status-pill">Held for review: <?= e($c['moderation_reason']) ?></p><?php endif; ?><p class="comment-body"><?= e($c['body']) ?></p><div class="review-actions"><?php foreach (['approve' => 'Approve comment', 'hold' => 'Hold comment', 'delete' => 'Delete comment'] as $action => $label): ?><form method="post" action="/admin/comment" <?= $action === 'delete' ? 'data-confirm="Delete this comment?"' : '' ?>><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$c['id'] ?>"><input type="hidden" name="action" value="<?= $action ?>"><button class="quiet-button"><?= $label ?></button></form><?php endforeach; ?></div></article><?php endforeach; ?><?php admin_pagination('/admin/comments', $page, $pages); ?>
